-- insert-salamanca-centers.sql
-- Inserta los 15 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Salamanca capital investigados y humanizados en este sprint.
-- Fuente primaria: dataset abierto "Directorio de Centros Docentes" de la Junta de
-- Castilla y Leon (analisis.datosabiertos.jcyl.es), filtrado por
-- refine.municipio=SALAMANCA y refine.denominacion_generica en
-- {'ESCUELA DE EDUCACION INFANTIL', 'CENTRO PRIVADO DE EDUCACION INFANTIL'}.
-- Complementado con el listado oficial "Escuelas de Educacion Infantil - Titularidad
-- Junta Castilla y Leon" (educa.jcyl.es), la web oficial de las Escuelas Infantiles
-- Municipales de Salamanca (Fundacion Salamanca Ciudad de Cultura y de Saberes /
-- Ayuntamiento de Salamanca), el listado oficial de centros adheridos al programa de
-- gratuidad de primer ciclo curso 2026-2027 (educa.jcyl.es) y webs oficiales propias
-- de un subconjunto de centros privados. Ver docs/data-sources-salamanca.md y
-- data/enrichment/salamanca-centers.json.
--
-- Ambito: unicamente el termino municipal de Salamanca capital
-- (refine.municipio=SALAMANCA en la fuente oficial, clasificacion administrativa
-- municipal). No se mezclan otros municipios de la provincia de Salamanca (Santa
-- Marta de Tormes, Carbajosa de la Sagrada, Villamayor, Cabrerizos, Aldeatejada,
-- Doninos de Salamanca, Castellanos de Moriscos, etc.) aunque aparecieran en la
-- misma fuente provincial/autonomica.
--
-- Ownership: se ha usado 'publico' para los 7 centros de titularidad publica
-- genuina: 3 Escuelas de Educacion Infantil (EEI) de titularidad de la Junta de
-- Castilla y Leon (Lazarillo de Tormes, San Bernardo, Virgen de la Vega) y 4
-- Escuelas Infantiles Municipales (EIM) del Ayuntamiento de Salamanca (Los
-- Pizarrales, El Rollo, Garrido, El Zurguen). Los 8 centros privados llevan
-- ownership='privado', nunca 'concertado': el mecanismo de financiacion de
-- Castilla y Leon para el primer ciclo de infantil privado es una subvencion
-- directa a centros adheridos a la oferta gratuita de plazas (Orden EDU/95/2022 y
-- normativa de desarrollo), no un concierto educativo formal. El unico centro del
-- listado oficial con concierto='S' (El Globo Rojo) se ha excluido del dataset
-- final por no poder verificar que ese concierto corresponda especificamente al
-- primer ciclo 0-3 anos frente al segundo ciclo (3-6 anos) del mismo centro. Ver
-- docs/salamanca-quality-report.md, seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga, Alicante, Las Palmas, Cordoba,
-- Granada, Valladolid, Jerez de la Frontera y Castellon de la Plana).
-- No toca ningun centro de ninguna otra ciudad ya integrada.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar. NO EJECUTADO POR EL AGENTE.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "salamanca" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('salamanca', 'Salamanca', 'Salamanca', 'Castilla y Leon')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('lazarillo-de-tormes-salamanca', 'Lazarillo de Tormes', 'escuela-infantil', 'publico', 'C/ Maestro Serrano, 7', '37008', 'salamanca', 'Salamanca', NULL, NULL, NULL, 40.94904, -5.65911, '923219922', NULL, NULL, 4, 36, NULL, ARRAY['comedor']::text[], 'Lazarillo de Tormes es una escuela infantil de titularidad de la Junta de Castilla y León en C/ Maestro Serrano, 7, 37008, dentro de la red pública autonómica de primer ciclo de educación infantil (0-3 años) de Salamanca.', 'Lazarillo de Tormes es una escuela infantil de titularidad de la Junta de Castilla y León, con sede en C/ Maestro Serrano, 7, 37008, Salamanca.

Forma parte de la red de Escuelas de Educación Infantil (EEI) de titularidad autonómica en Castilla y León, que imparte el primer ciclo de educación infantil (0-3 años) con plazas gratuitas para todas las familias desde el curso 2024-2025, dentro del programa de gratuidad del primer ciclo de educación infantil de la Junta de Castilla y León. Según el listado oficial de titularidad JCyL, el centro cuenta con 5 unidades y 74 plazas.

Según el registro oficial de centros docentes, el centro ofrece servicio de comedor.

Para conocer el proceso de admisión, unidades disponibles y horario detallado, se recomienda contactar directamente con el centro o consultar el Portal de Educación de la Junta de Castilla y León.', '{}'::text[], '[{"question":"¿Dónde está ubicada la escuela infantil Lazarillo de Tormes?","answer":"Se encuentra en C/ Maestro Serrano, 7, 37008, en Salamanca."},{"question":"¿Qué edades atiende este centro?","answer":"Es una escuela infantil de primer ciclo de educación infantil, dirigida a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad pública, perteneciente a la red de Escuelas de Educación Infantil de la Junta de Castilla y León."},{"question":"¿Es gratuita la plaza en este centro?","answer":"Sí. Desde el curso 2024-2025, Castilla y León ofrece gratuidad total del primer ciclo de educación infantil (0-3 años) en los centros de titularidad de la Junta, dentro del programa de gratuidad de estas enseñanzas."},{"question":"¿Tiene servicio de comedor?","answer":"Sí, según el registro oficial de centros docentes de Castilla y León, el centro cuenta con servicio de comedor."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 923219922."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://analisis.datosabiertos.jcyl.es/explore/dataset/directorio-de-centros-docentes/', ARRAY['https://www.educa.jcyl.es/es/admision-alumnado/admision-centros-imparten-primer-ciclo-educacion-infantil/listado-escuelas-infantiles-titularidad-jcyl','https://www.educa.jcyl.es/es/admision-alumnado/admision-centros-imparten-primer-ciclo-educacion-infantil/listado-centros-plazas-gratuitas-0-3-anos-curso-2026-2027']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
